import struct, subprocess, os, sys

def segments(data):
    i = 0
    out = []
    while i < len(data) - 1:
        m = struct.unpack('>H', data[i:i+2])[0]
        if m == 0xFF4F:
            out.append(('SOC', i, 2, None)); i += 2; continue
        if m == 0xFFD9:
            out.append(('EOI', i, 2, None)); i += 2; continue
        if m == 0xFF93:
            out.append(('SOD', i, 2, None)); i += 2
            out.append(('DATA', i, len(data)-i, None)); i = len(data); continue
        if data[i] != 0xFF:
            i += 1; continue
        L = struct.unpack('>H', data[i+2:i+4])[0]
        out.append(('%04X' % m, i, L+2, data[i:i+L+2]))
        i += L + 2
    return out

for name, off, ln, raw in segments(open('base.jpc','rb').read()):
